import{_ as i,A as p,o,c as d,O as r,b as g,w as n,Z as e,E as a,a as l}from"./chunks/framework.2c2d5a61.js";const b=JSON.parse('{"title":"Netty","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/12-Netty.md","filePath":"interview/后端/Java/12-Netty.md","lastUpdated":null}'),h={name:"interview/后端/Java/12-Netty.md"};function c(y,t,u,B,E,N){const s=p("Mermaid");return o(),d("div",null,[t[2]||(t[2]=r('<h1 id="netty" tabindex="-1">Netty <a class="header-anchor" href="#netty" aria-label="Permalink to &quot;Netty&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-netty-是什么、其设计哲学-★★★" tabindex="-1">1. Netty 是什么、其设计哲学 ★★★ <a class="header-anchor" href="#_1-netty-是什么、其设计哲学-★★★" aria-label="Permalink to &quot;1. Netty 是什么、其设计哲学 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Netty</strong> 是一个基于 Java NIO 的<strong>异步事件驱动</strong>的高性能网络应用框架，用来快速开发高性能、高可靠的网络服务器和客户端。它把 NIO 里那些难用又容易出错的底层细节（Selector、ByteBuffer、Channel）全部封装掉，用「<strong>Channel + Pipeline + Handler</strong>」这套<strong>组件化模型</strong>，让网络编程像搭积木一样。设计哲学就几条：<strong>异步非阻塞</strong>、<strong>事件驱动</strong>、<strong>组件可插拔</strong>、追求高性能（<strong>零拷贝</strong>、内存池、无锁化）。</p><p><strong>我的项目关联</strong> 我们<strong>网关服务</strong>就是基于 <strong>Netty</strong> 开发的：充电桩通过 <strong>TCP 长连接</strong>持续上报报文（心跳、充电状态、计量数据），网关用 Netty 接收、解析，再通过 <strong>Kafka</strong> 转发给下游微服务；反过来，下游要<strong>下发控制指令</strong>（启动/停止充电）时，也走 Netty 把报文推回给对应充电桩。选 Netty 的原因很直接——设备多、长连接多、报文频繁，需要<strong>高并发</strong>且稳定的 IO 处理能力。</p><p><strong>面试答题话术</strong> 「Netty 是<strong>异步事件驱动</strong>的网络框架，底层封装了 Java NIO，提供统一的 API。核心是<strong>非阻塞 IO + Reactor 线程模型</strong>，把<strong>连接管理和业务处理解耦</strong>。设计哲学可以概括为：屏蔽 NIO 的复杂性、<strong>组件化可插拔</strong>（Pipeline、Handler、Codec 都能自定义替换）、高性能（<strong>零拷贝</strong>、内存池、<strong>无锁化串行设计</strong>）。它最适合做<strong>高并发长连接</strong>场景，比如我们充电桩网关这种设备接入层，几千个设备长连接就靠少量 <strong>worker 线程</strong>撑着。」</p><hr><h2 id="_2-netty-相比传统-java-网络编程-bio-nio-的优势-★★★" tabindex="-1">2. Netty 相比传统 Java 网络编程（BIO/NIO）的优势 ★★★ <a class="header-anchor" href="#_2-netty-相比传统-java-网络编程-bio-nio-的优势-★★★" aria-label="Permalink to &quot;2. Netty 相比传统 Java 网络编程（BIO/NIO）的优势 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>BIO</strong> 是<strong>同步阻塞</strong>，一个连接一个线程，线程阻塞在 read 上等数据，连接一多<strong>线程就爆炸</strong>，CPU 大量时间花在<strong>线程切换</strong>上。<strong>NIO</strong> 虽然用 <strong>Selector</strong> 一个线程管多个连接，但<strong>原生 API 太底层、难用</strong>：ByteBuffer 读写要 flip、<strong>粘包半包要自己处理</strong>、还有臭名昭著的 <strong>epoll 空轮询 bug</strong>，写起来又臭又长。Netty 把这些坑都填了，还额外做了性能优化。</p><p><strong>我的项目关联</strong> 网关如果直接用 <strong>BIO</strong> 写，几千个充电桩长连接就得开<strong>几千个线程</strong>，光<strong>线程栈内存</strong>就能把容器撑爆，根本扛不住。实际我们是 <strong>Netty + 少量 worker 线程</strong>撑起几千设备连接，<strong>编解码</strong>、<strong>粘包拆包</strong>、空闲检测这些全用 Netty <strong>开箱即用的 Handler</strong>，不用自己造轮子，开发效率和稳定性都上来了。</p><p><strong>面试答题话术</strong> 「<strong>BIO</strong> 是同步阻塞，一个连接一个线程，连接多了<strong>线程数爆炸</strong>、上下文切换开销大；<strong>NIO</strong> 是同步非阻塞，用 <strong>Selector 多路复用</strong>，一个线程管多个连接，但原生 API 难用、坑多，比如 <strong>epoll 空轮询 bug</strong>、ByteBuffer 读写要切换、粘包拆包要自己写；AIO 是异步非阻塞，但生态不成熟、用得少。<strong>Netty</strong> 封装了 NIO，提供统一的异步事件驱动 API，自带编解码器、粘包处理、<strong>零拷贝</strong>、内存池、<strong>Reactor 线程模型</strong>，性能和开发效率都比原生高。一句话：<strong>BIO 连接多了扛不住，NIO 太底层难写，Netty 是 NIO 的高层封装加优化</strong>。」</p><hr><h2 id="_3-netty-的-reactor-模型及单线程-多线程-主从多线程三种模式-★★★" tabindex="-1">3. Netty 的 Reactor 模型及单线程/多线程/主从多线程三种模式 ★★★ <a class="header-anchor" href="#_3-netty-的-reactor-模型及单线程-多线程-主从多线程三种模式-★★★" aria-label="Permalink to &quot;3. Netty 的 Reactor 模型及单线程/多线程/主从多线程三种模式 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Reactor</strong> 是一种 <strong>IO 多路复用</strong>的<strong>事件分发模型</strong>：一个（或一组）线程负责监听所有连接的 IO 事件，事件到了就分发给对应的 handler 处理。三种模式：<strong>单线程</strong>——一个线程既 accept 又读写又处理业务，串行，一个 handler 慢就全卡住，只适合小并发；<strong>多线程</strong>——一个 Reactor 线程负责 accept 和分发，业务处理丢进<strong>线程池</strong>，IO 线程不再被业务阻塞；<strong>主从多线程</strong>——一个 main Reactor（boss）只 accept，多个 sub Reactor（worker）各自分管一部分连接的读写，业务再丢线程池。<strong>Netty 默认就是主从多线程</strong>。</p>',15)),(o(),g(e,null,{default:n(()=>[a(s,{id:"mermaid-75",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5Bmain%20Reactor%3Cbr%2F%3EbossGroup%5D%20--%3E%7Caccept%20%E8%BF%9E%E6%8E%A5%7C%20B%5Bsub%20Reactor%3Cbr%2F%3EworkerGroup%5D%0A%20%20%20%20B%20--%3E%7C%E5%88%86%E9%85%8D%E8%BF%9E%E6%8E%A5%E8%AF%BB%E5%86%99%7C%20C%5BThreadPool%3Cbr%2F%3E%E4%B8%9A%E5%8A%A1%E5%A4%84%E7%90%86%5D%0A"})]),fallback:n(()=>t[0]||(t[0]=[l(" Loading... ")])),_:1})),t[3]||(t[3]=r('<p><strong>我的项目关联</strong> 网关用的就是<strong>主从多线程模型</strong>：<strong>bossGroup</strong> 专门负责 accept 充电桩的连接，<strong>workerGroup</strong> 负责连接的读写。这跟充电桩场景天然匹配——连接多、IO 频繁，把「<strong>建连</strong>」和「<strong>读写</strong>」拆开，再把「读写」和「<strong>业务处理</strong>」拆开，避免一个报文的解析卡住所有连接。</p><p><strong>面试答题话术</strong> 「<strong>Reactor 是事件驱动的 IO 模型</strong>，核心是『<strong>一个事件分发器 + 多个处理器</strong>』。单 Reactor 单线程：一个线程既 accept 又读写又处理，全<strong>串行</strong>，适合小场景；单 Reactor 多线程：一个线程只 accept 和分发，业务 handler 丢<strong>线程池</strong>，读写不再被业务阻塞；主从 Reactor 多线程：boss 只管 accept，worker 只管连接读写，这是 <strong>Netty 默认模型</strong>，也是生产最常用的。我们网关就是 <strong>boss 接连接、worker 读写报文</strong>的模式，连接多的时候这个分工特别重要。」</p><hr><h2 id="_4-netty-的核心组件有哪些-channel、eventloop、channelpipeline、channelhandler、bytebuf、bootstrap-★★★" tabindex="-1">4. Netty 的核心组件有哪些（Channel、EventLoop、ChannelPipeline、ChannelHandler、ByteBuf、Bootstrap）★★★ <a class="header-anchor" href="#_4-netty-的核心组件有哪些-channel、eventloop、channelpipeline、channelhandler、bytebuf、bootstrap-★★★" aria-label="Permalink to &quot;4. Netty 的核心组件有哪些（Channel、EventLoop、ChannelPipeline、ChannelHandler、ByteBuf、Bootstrap）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 六个核心组件，一句话各说清楚：<strong>Channel</strong> 是对 Socket 的抽象，代表一条连接，读写都通过它；<strong>EventLoop/EventLoopGroup</strong> 是事件循环线程，一个 EventLoop 绑定一个线程，管理一组 Channel 的所有 IO 和任务；<strong>ChannelPipeline</strong> 是责任链，链上挂着一串 ChannelHandler，数据按顺序经过；<strong>ChannelHandler</strong> 是处理器，分<strong>入站</strong>和<strong>出站</strong>两类；<strong>ByteBuf</strong> 是 Netty 的字节容器，比原生 ByteBuffer 好用，读写指针分离、支持池化、引用计数；<strong>Bootstrap/ServerBootstrap</strong> 是启动引导类，配置完参数后拉起服务端或客户端。</p><p><strong>我的项目关联</strong> 网关里这套组件全用上了：<strong>ServerBootstrap</strong> 配 boss/worker 两个线程组；每条充电桩连接对应一个 <strong>Channel</strong>，在 <strong>ChannelInitializer</strong> 里挂上<strong>粘包解码</strong>、协议编解码、心跳检测、业务 handler；报文用 <strong>ByteBuf</strong> 收发，处理完要按<strong>引用计数 release</strong>；<strong>EventLoop</strong> 负责撑起几千连接的读写。这套组件关系我对着自己代码就能讲清楚，是<strong>简历亮点</strong>。</p><p><strong>面试答题话术</strong> 「六个核心组件：<strong>Channel</strong> 抽象一条连接；<strong>EventLoop</strong> 是事件循环，一个线程管一组 Channel；<strong>ChannelPipeline</strong> 是责任链，按顺序挂 Handler；Handler 分<strong>入站出站</strong>，做编解码和业务处理；<strong>ByteBuf</strong> 是字节容器，<strong>读写指针分离</strong>、支持池化和引用计数；<strong>Bootstrap</strong> 负责启动配置。它们的关系是：Bootstrap 创建 Channel，Channel 绑定到一个 EventLoop，数据在 Pipeline 的 Handler 链上流转，Handler 里用 ByteBuf 读写数据。这套关系是理解 Netty 的<strong>骨架</strong>。」</p><hr><h2 id="_5-channelpipeline-的作用、入站出站-handler-执行顺序-★★★" tabindex="-1">5. ChannelPipeline 的作用、入站出站 handler 执行顺序 ★★★ <a class="header-anchor" href="#_5-channelpipeline-的作用、入站出站-handler-执行顺序-★★★" aria-label="Permalink to &quot;5. ChannelPipeline 的作用、入站出站 handler 执行顺序 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>ChannelPipeline</strong> 是一条双向链表结构的<strong>责任链</strong>。<strong>入站事件</strong>（读数据）从链头往链尾依次触发 <strong>InboundHandler</strong>；<strong>出站事件</strong>（写数据）从链尾往链头依次触发 <strong>OutboundHandler</strong>，方向是反的。要特别注意写数据的两种方式：用 <strong>ChannelHandlerContext 的 write</strong> 是从当前 handler 往前找 OutboundHandler，用 <strong>Channel 的 write</strong> 是从链尾开始找，两者<strong>起点不一样</strong>。</p>',10)),(o(),g(e,null,{default:n(()=>[a(s,{id:"mermaid-102",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E5%85%A5%E7%AB%99%E6%95%B0%E6%8D%AE%5D%20--%3E%20B%5BInbound%20%E8%A7%A3%E7%A0%81%E5%99%A8%3Cbr%2F%3E%E7%B2%98%E5%8C%85%C2%B7%E5%8D%8F%E8%AE%AE%5D%0A%20%20%20%20B%20--%3E%20C%5BInbound%20%E4%B8%9A%E5%8A%A1%20handler%5D%0A%20%20%20%20C%20--%3E%20D%5BOutbound%20%E7%BC%96%E7%A0%81%E5%99%A8%3Cbr%2F%3E%E5%8D%8F%E8%AE%AE%C2%B7%E5%B8%A7%5D%0A%20%20%20%20D%20--%3E%20E%5B%E5%87%BA%E7%AB%99%E6%95%B0%E6%8D%AE%5D%0A"})]),fallback:n(()=>t[1]||(t[1]=[l(" Loading... ")])),_:1})),t[4]||(t[4]=r('<p><strong>我的项目关联</strong> 网关的 <strong>Pipeline 顺序</strong>是入站：<strong>粘包解码器</strong>（ByteToMessageDecoder）→ <strong>协议解码器</strong> → 业务 handler；出站：<strong>协议编码器</strong> → <strong>帧编码器</strong>。这个顺序一旦搞反，粘包就处理错、报文解析就乱。还有一个我们真遇到过的点（<strong>线上</strong>）：在下发指令的业务 handler 里，用错了 <strong>write 的调用对象</strong>，导致数据没走完整条编码链，报文格式不对，充电桩那边解析失败——排查后确认要用 <strong>ctx.write</strong> 让数据从当前位置继续走完整条 outbound 链。</p><p><strong>面试答题话术</strong> 「<strong>Pipeline 是责任链</strong>，<strong>入站事件</strong>从链头到尾执行 <strong>InboundHandler</strong>，<strong>出站事件</strong>从链尾到头执行 <strong>OutboundHandler</strong>，两个方向是反的。典型顺序：入站先粘包解码、再协议解码、最后业务处理；出站先业务编码、再帧编码。注意一个细节：用 <strong>ChannelHandlerContext.write</strong> 是从当前 handler 往前触发 OutboundHandler，用 <strong>Channel.write</strong> 是从链尾触发，两者<strong>起点不同</strong>，很多 bug 就是这里搞混了。」</p><hr><h2 id="_6-netty-中如何解决-tcp-粘包-拆包-★★★" tabindex="-1">6. Netty 中如何解决 TCP 粘包/拆包 ★★★ <a class="header-anchor" href="#_6-netty-中如何解决-tcp-粘包-拆包-★★★" aria-label="Permalink to &quot;6. Netty 中如何解决 TCP 粘包/拆包 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>TCP 是字节流，没有消息边界</strong>，所以会出现<strong>粘包</strong>（多个小包粘在一起）和<strong>拆包</strong>（一个大包被拆成多段）。原因是发送方缓冲、接收方读取不及时、<strong>MSS/MTU 限制</strong>。解决思路就三条：定长消息、分隔符、消息头带长度字段。Netty 内置了对应解码器：<strong>FixedLengthFrameDecoder</strong>（定长）、<strong>DelimiterBasedFrameDecoder</strong>（分隔符）、<strong>LengthFieldBasedFrameDecoder</strong>（长度字段），<strong>开箱即用</strong>。</p><p><strong>我的项目关联</strong> 我们充电桩<strong>协议报文头带长度字段</strong>，网关用 <strong>LengthFieldBasedFrameDecoder</strong> 按长度字段拆帧，这是<strong>线上</strong>真实场景。<strong>通用坑</strong>：如果直接继承 <strong>ByteToMessageDecoder</strong> 不做粘包处理，会出现一个 buffer 里塞了多个帧、或者<strong>半包解析错乱</strong>——这是资料里学到的经典坑，我们接设备协议第一步就把<strong>帧边界</strong>定清楚，没真踩过。</p><p><strong>面试答题话术</strong> 「<strong>TCP 是字节流没有消息边界</strong>，所以会<strong>粘包拆包</strong>：粘包是多个小包粘成一个，拆包是一个大包被拆成多段。原因是发送缓冲、接收缓冲、MTU 限制。解决方案三种：定长消息、分隔符、消息头带长度字段。Netty 对应提供 <strong>FixedLengthFrameDecoder</strong>、<strong>DelimiterBasedFrameDecoder</strong>、<strong>LengthFieldBasedFrameDecoder</strong>。我们充电桩协议报文头带长度，就用 LengthFieldBasedFrameDecoder 拆帧，接自定义协议第一件事就是把<strong>边界</strong>定清楚。」</p><hr><h2 id="_7-netty-高性能表现在哪些方面-★★★" tabindex="-1">7. Netty 高性能表现在哪些方面 ★★★ <a class="header-anchor" href="#_7-netty-高性能表现在哪些方面-★★★" aria-label="Permalink to &quot;7. Netty 高性能表现在哪些方面 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 高性能来自几个层面的组合：<strong>Reactor 线程模型</strong>——少量线程撑大量连接，减少线程切换；<strong>零拷贝</strong>——减少数据在<strong>内核态和用户态</strong>之间的搬运；<strong>内存池</strong>——ByteBuf 池化复用，减少对象创建和 <strong>GC 压力</strong>；<strong>无锁化串行设计</strong>——同一 Channel 的 IO 事件和任务都在同一个 EventLoop 线程执行，天然不用加锁；高效数据结构——<strong>FastThreadLocal</strong>、<strong>MPSC</strong>（多生产者单消费者）队列等。</p><p><strong>我的项目关联</strong> 网关几千个充电桩长连接，<strong>worker 线程数远小于连接数</strong>，这就是 <strong>Reactor 多路复用</strong>的直接收益。内存方面我们开了 <strong>Netty 内存泄漏检测</strong>（io.netty.leakDetection.level）配合<strong>池化分配器</strong>，监控<strong>直接内存</strong>占用，避免 ByteBuf 频繁创建导致 <strong>GC 抖动</strong>。高性能不是玄学，是这几项叠加出来的。</p><p><strong>面试答题话术</strong> 「Netty 高性能体现在：一是 <strong>Reactor 多路复用</strong>，少量线程处理大量连接；二是<strong>零拷贝</strong>，减少<strong>内核态和用户态</strong>的数据搬运；三是 <strong>ByteBuf 内存池</strong>，复用缓冲减少 GC 压力；四是<strong>无锁化串行设计</strong>，同一 Channel 的事件都在同一个 EventLoop 线程执行，避免锁竞争；五是高效的数据结构，比如 <strong>FastThreadLocal</strong>、<strong>MPSC 队列</strong>。这几项叠加起来就是<strong>高吞吐、低延迟</strong>。」</p><hr><h2 id="_8-netty-的零拷贝技术如何实现-★★★" tabindex="-1">8. Netty 的零拷贝技术如何实现 ★★★ <a class="header-anchor" href="#_8-netty-的零拷贝技术如何实现-★★★" aria-label="Permalink to &quot;8. Netty 的零拷贝技术如何实现 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> Netty 的<strong>零拷贝</strong>不是字面上「完全不拷贝」，而是「减少不必要的拷贝」。几个层面：<strong>直接内存</strong>——用<strong>堆外 ByteBuf</strong>，省掉堆内和堆外之间的一次拷贝；<strong>CompositeByteBuf</strong>——把多个 ByteBuf 组合成一个<strong>逻辑视图</strong>，不实际合并拷贝；<strong>FileRegion 的 transferTo</strong>——底层用操作系统 <strong>sendfile</strong>，文件数据从内核态直接发到 socket，不经过用户态；<strong>slice/wrap</strong>——对已有缓冲做切片和包装，都是视图操作不复制数据。</p><p><strong>我的项目关联</strong> 网关收发报文默认用<strong>堆外直接内存</strong>（<strong>PooledByteBufAllocator</strong>），省一次拷贝。零拷贝跟「<strong>直接内存要 release</strong>」是绑在一起的：堆外内存不在 <strong>GC 管辖范围</strong>，所以 ByteBuf 必须严格按<strong>引用计数 release</strong>，我们还用 io.netty.leakDetection.level 在测试环境先照<strong>内存泄漏</strong>。这块能跟「<strong>直接内存 OOM</strong>」连起来讲。</p><p><strong>面试答题话术</strong> 「Netty 零拷贝有几种：一是<strong>堆外直接内存</strong>，避免堆内堆外拷贝；二是 <strong>CompositeByteBuf</strong>，把多个缓冲逻辑组合不实际拷贝；三是 <strong>FileRegion.transferTo</strong>，用操作系统 <strong>sendfile</strong>，文件从内核直接发到 socket 不经用户态；四是 <strong>slice 和 wrap</strong>，都是<strong>视图操作</strong>不复制。核心是<strong>减少不必要的内存拷贝，而不是完全不拷贝</strong>。代价是堆外内存要手动管理，所以 ByteBuf 要按<strong>引用计数 release</strong>。」</p><hr><h2 id="_9-netty-的线程模型如何设计-★★★" tabindex="-1">9. Netty 的线程模型如何设计 ★★★ <a class="header-anchor" href="#_9-netty-的线程模型如何设计-★★★" aria-label="Permalink to &quot;9. Netty 的线程模型如何设计 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> Netty 线程模型的核心是 <strong>EventLoop 体系</strong>：<strong>NioEventLoopGroup</strong> 是一组 EventLoop，每个 EventLoop <strong>绑定一个线程</strong>。<strong>boss 线程组</strong>负责 accept 连接，<strong>worker 线程组</strong>负责连接读写。一个 EventLoop 会被分配多个 Channel，同一 Channel 的所有 IO 事件和任务都在同一个线程里串行执行，<strong>天然无锁</strong>，这就是<strong>无锁化设计</strong>的来源。整个模型 = <strong>读写分离 + 事件循环 + 任务队列</strong>。</p><p><strong>我的项目关联</strong> 网关启动时 <strong>bossGroup</strong> 一般设 1 个线程（只 accept 够用了），<strong>workerGroup</strong> 按 <strong>CPU 核数 × 2</strong> 设。每个充电桩连接建立后被分配到一个固定的 <strong>worker EventLoop</strong>，之后这个连接的所有报文读写、<strong>心跳超时检测</strong>都在同一个线程执行，所以 handler 里<strong>不用加锁</strong>。这个「<strong>一条连接绑定一个线程</strong>」的设计让我对 Netty 的<strong>串行无锁</strong>理解很深。</p><p><strong>面试答题话术</strong> 「Netty 线程模型核心是 <strong>EventLoop</strong>：每个 EventLoop 是一个单线程执行器，一个 EventLoop 管理多个 Channel，同一个 Channel 的所有事件和任务都在同一个线程执行，所以<strong>不需要加锁</strong>。<strong>boss 组</strong>只负责 accept，<strong>worker 组</strong>负责连接读写，这就是<strong>主从 Reactor</strong>。好处是<strong>线程少、无锁、上下文切换少</strong>。实践上 boss 设 1 个线程，worker 按 <strong>CPU 核数两倍</strong>，连接被固定到一个 worker 线程上<strong>串行处理</strong>。」</p><hr><h2 id="_10-netty-的典型应用场景-★★☆" tabindex="-1">10. Netty 的典型应用场景 ★★☆ <a class="header-anchor" href="#_10-netty-的典型应用场景-★★☆" aria-label="Permalink to &quot;10. Netty 的典型应用场景 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> Netty 适合<strong>高并发、长连接、自定义协议</strong>的通信场景：<strong>RPC 框架</strong>底层（<strong>Dubbo</strong> 默认用 Netty）、消息中间件（<strong>RocketMQ</strong>）、分布式协调（<strong>Zookeeper</strong>）、网关、即时通讯、游戏服务器、<strong>物联网设备接入</strong>。不适合的场景是普通<strong>短连接 HTTP 接口</strong>——那是 <strong>Tomcat</strong> 这类 <strong>Servlet 容器</strong>的活，Netty 也能写 HTTP 但没必要。</p><p><strong>我的项目关联</strong> 我们网关就是典型的<strong>物联网设备接入</strong>场景：充电桩长连接上报报文、网关下发<strong>控制指令</strong>，协议<strong>完全自定义</strong>。另外项目里 <strong>Kafka 消费线程</strong>和 Netty 的 <strong>worker 线程</strong>配合——消费到控制指令后，通过<strong>设备会话管理</strong>找到对应连接再下发。这正好是 Netty 最对口的场景之一，简历上可以重点讲。</p><p><strong>面试答题话术</strong> 「Netty 适合<strong>高并发长连接、自定义协议</strong>的场景：RPC 框架（<strong>Dubbo</strong> 底层就是 Netty）、消息中间件（<strong>RocketMQ</strong>）、分布式组件（<strong>Zookeeper</strong>）、网关、即时通讯、游戏服务器、<strong>物联网设备接入</strong>。不适合的场景是普通<strong>短连接 HTTP 接口</strong>，用 Tomcat 这类 Servlet 容器更省事。我们项目用它做<strong>充电桩设备接入网关</strong>，就是典型的物联网设备接入场景，<strong>长连接 + 自定义协议 + 心跳保活</strong>。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>BIO</strong> 一个连接一个线程，<strong>NIO</strong> 一个线程多个连接，<strong>Netty</strong> 是 NIO 的<strong>高层封装加优化</strong>。</li><li><strong>Reactor 三模式</strong>：<strong>单线程、多线程、主从多线程</strong>，Netty 默认主从多线程。</li><li><strong>粘包拆包三个解法</strong>：<strong>定长、分隔符、长度字段</strong>，Netty 都有<strong>现成解码器</strong>。</li><li><strong>零拷贝不是不拷贝，是少拷贝</strong>：直接内存、<strong>CompositeByteBuf</strong>、<strong>sendfile</strong>、slice。</li><li>一个 <strong>Channel</strong> 的所有事件都在同一个 <strong>EventLoop 线程</strong>执行，<strong>天然无锁</strong>。</li></ul>',30))])}const f=i(h,[["render",c]]);export{b as __pageData,f as default};
